import { PlaneGeometry, Mesh, MeshStandardNodeMaterial, DoubleSide, Group, Vector2 } from 'three/webgpu';
import { gsap } from 'gsap';
import { parallaxScroll, depthRotate } from '@/primitives';

export default function createNode(config, ctx) {
  const group = new Group();

  // Load textures
  const imagePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  const depthPromise = ctx.textureLoader.loadTexture(config.depthMapUrl);

  // Create geometry with enough segments for displacement
  const geometry = new PlaneGeometry(3.5, 2.5, 64, 64);

  // Create material
  const material = new MeshStandardNodeMaterial({
    side: DoubleSide,
    roughness: 0.6,
    metalness: 0.3,
    clearcoat: 0.15,
    color: 0xffffff,
    displacementScale: 0.12,
    displacementBias: 0,
  });

  // Apply textures when loaded
  Promise.all([imagePromise, depthPromise]).then(([imageTex, depthTex]) => {
    material.map = imageTex;
    material.displacementMap = depthTex;
    material.needsUpdate = true;
  });

  const mesh = new Mesh(geometry, material);
  mesh.position.z = 0;
  group.add(mesh);

  // Weighted-settle entrance
  const entranceTimeline = gsap.timeline();
  entranceTimeline.fromTo(mesh.scale, { x: 0.96, y: 0.96, z: 0.96 }, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out', overwrite: 'auto' });
  entranceTimeline.fromTo(mesh.position, { y: 0.4 }, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);

  // Apply cinematic primitives
  const primitivesCleanups = [];
  const primitivesToApply = config.cinematicPrimitives || [];
  for (const p of primitivesToApply) {
    const result = ctx.primitives[p.name](group, p.params);
    if (result && result.cleanup) primitivesCleanups.push(result.cleanup);
  }

  // Hover handler: rise-in subtle
  const hoverIn = () => {
    gsap.to(mesh.position, { y: 0.15, duration: 0.3, ease: 'power2.out' });
  };
  const hoverOut = () => {
    gsap.to(mesh.position, { y: 0, duration: 0.3, ease: 'power2.out' });
  };

  // Click handler: emit event
  const clickHandler = () => {
    ctx.emit('navigate', { to: 'hub-pricing.select' });
  };

  // Attach handlers
  group.userData.handlers = {
    pointerover: hoverIn,
    pointerout: hoverOut,
    click: clickHandler,
  };

  // Cleanup
  group.userData.cleanup = () => {
    entranceTimeline.kill();
    primitivesCleanups.forEach(fn => fn());
    geometry.dispose();
    material.dispose();
    // Textures are cached, no need to dispose
  };

  return group;
}
